import{_ as a}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as r,o as e,af as o}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const u=JSON.parse('{"title":"ChatGPT Work","description":"","frontmatter":{},"headers":[],"relativePath":"zh/products/ai-coding/codex/chatgpt-work.md","filePath":"zh/products/ai-coding/codex/chatgpt-work.md","lastUpdated":1787107158000}'),d={name:"zh/products/ai-coding/codex/chatgpt-work.md"};function s(l,t,h,n,i,c){return e(),r("div",null,[...t[0]||(t[0]=[o(`<h1 id="chatgpt-work" tabindex="-1">ChatGPT Work <a class="header-anchor" href="#chatgpt-work" aria-label="Permalink to &quot;ChatGPT Work&quot;">​</a></h1><blockquote><p>ChatGPT Work 是把一件事<strong>做到可审结果</strong>的代理模式：调研、做表、写稿、建站点、定期更新。它不是聊天，也不是写代码的 Codex。</p><p>官方原文：「ChatGPT Work is a way to delegate real work to ChatGPT。」入口：<a href="https://learn.chatgpt.com/docs/get-started-with-work" target="_blank" rel="noreferrer">Get started with ChatGPT Work</a>。</p></blockquote><h2 id="先决条件" tabindex="-1">先决条件 <a class="header-anchor" href="#先决条件" aria-label="Permalink to &quot;先决条件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>要求</th></tr></thead><tbody><tr><td>账号</td><td>任意 ChatGPT 套餐；具体入口和额度以<a href="https://learn.chatgpt.com/docs/pricing" target="_blank" rel="noreferrer">定价页</a>为准</td></tr><tr><td>网页</td><td><a href="https://chatgpt.com/" target="_blank" rel="noreferrer">chatgpt.com</a> 的 Work 开关</td></tr><tr><td>桌面</td><td><a href="https://learn.chatgpt.com/docs/app" target="_blank" rel="noreferrer">ChatGPT 桌面应用</a>（macOS / Windows；Linux 为预览）</td></tr><tr><td>本地文件 / 本机应用</td><td>桌面应用里选 <strong>Work locally</strong></td></tr><tr><td>关电脑还能跑</td><td>选 <strong>Cloud</strong>，或直接在网页上用 Work</td></tr></tbody></table><p><strong>学习目标</strong>：分清 Chat / Work / Codex；能交一件有明确产出的任务；知道本地和云端差在哪；会用插件和定期任务。</p><p><strong>非目标</strong>：本页不讲 CLI 沙箱配置（见 <a href="./codex-cli.html">Codex CLI</a>），不写价格数字（见 <a href="./chatgpt-plus.html">套餐与访问</a>）。</p><h2 id="work-是什么-不是什么" tabindex="-1">Work 是什么，不是什么 <a class="header-anchor" href="#work-是什么-不是什么" aria-label="Permalink to &quot;Work 是什么，不是什么&quot;">​</a></h2><p>官方把同一桌面应用切成三种工作方式：</p><table tabindex="0"><thead><tr><th>选</th><th>你要的是</th><th>例子</th></tr></thead><tbody><tr><td><strong>Chat</strong></td><td>问答、头脑风暴、短草稿</td><td>比方案、改一封邮件、澄清需求</td></tr><tr><td><strong>ChatGPT Work</strong></td><td>有结果可审的任务</td><td>八页 PPT、对比表、简报、定期议程</td></tr><tr><td><strong>Codex</strong></td><td>开发者视图和仓库级改动</td><td>修 bug、跑测试、审 PR、实现功能</td></tr></tbody></table><p>Work 会拆步骤、拉文件和插件、做到一份你能打开检查的产出。你可以跟进度、改方向、在关键动作上点批准。</p><p>它<strong>不是</strong>：</p><ul><li>替代 Codex 的编程界面（没有 PR 侧栏、默认隐藏 Git / shell 细节）</li><li>替代 Chat 的闲聊入口（短问题用 Chat 更省额度）</li><li>独立安装的第三个应用（2026-07-09 起，Work 和 Codex 都在 <a href="https://learn.chatgpt.com/docs/app" target="_blank" rel="noreferrer">ChatGPT 桌面应用</a>里）</li></ul><blockquote><p>官方说明：若你以前用 Codex 做非编程工作，可以继续留在 Codex，也可以改用 Work。能力重叠，界面不同——Work 面向日常知识工作。Work 与 Codex <strong>共用用量额度</strong>。</p></blockquote><h2 id="核心能力" tabindex="-1">核心能力 <a class="header-anchor" href="#核心能力" aria-label="Permalink to &quot;核心能力&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>实际能做什么</th><th>官方页</th></tr></thead><tbody><tr><td>调研与分析</td><td>搜索、浏览、比来源、读文件、汇总</td><td><a href="https://learn.chatgpt.com/docs/use-chatgpt" target="_blank" rel="noreferrer">Use ChatGPT</a></td></tr><tr><td>文件与工具</td><td>上传、Projects、Library、Memories、插件</td><td><a href="https://learn.chatgpt.com/docs/projects" target="_blank" rel="noreferrer">Projects</a> · <a href="https://learn.chatgpt.com/docs/plugins" target="_blank" rel="noreferrer">Plugins</a></td></tr><tr><td>成品文件</td><td>文档、演示、表格、PDF，预览后再下</td><td><a href="https://learn.chatgpt.com/docs/artifacts-viewer" target="_blank" rel="noreferrer">Work with files</a></td></tr><tr><td>视觉与站点</td><td>生图、可视化、用 <strong>Sites</strong> 托管网页/应用</td><td><a href="https://learn.chatgpt.com/docs/sites" target="_blank" rel="noreferrer">Sites</a></td></tr><tr><td>浏览器与本机</td><td>内置浏览器、Chrome 扩展、Computer Use、Appshots</td><td><a href="https://learn.chatgpt.com/docs/browser" target="_blank" rel="noreferrer">Browser</a></td></tr><tr><td>长任务</td><td>子代理拆分、长时间运行、中途改方向</td><td><a href="https://learn.chatgpt.com/docs/long-running-work" target="_blank" rel="noreferrer">Long-running work</a></td></tr><tr><td>重复工作</td><td>定期任务 + Skills</td><td><a href="https://learn.chatgpt.com/docs/automations" target="_blank" rel="noreferrer">Scheduled tasks</a></td></tr></tbody></table><p>能力随套餐、平台、地区、放量和 workspace 设置变化。管理员可以关 Work、插件、浏览器和网络。</p><h2 id="快速上手" tabindex="-1">快速上手 <a class="header-anchor" href="#快速上手" aria-label="Permalink to &quot;快速上手&quot;">​</a></h2><h3 id="_1-切到-work" tabindex="-1">1. 切到 Work <a class="header-anchor" href="#_1-切到-work" aria-label="Permalink to &quot;1. 切到 Work&quot;">​</a></h3><p>网页或桌面应用里打开切换器，选 <strong>Work</strong>。好任务有三件事：明确产出、少量源材料、你能审的结果。</p><h3 id="_2-选本地还是云端" tabindex="-1">2. 选本地还是云端 <a class="header-anchor" href="#_2-选本地还是云端" aria-label="Permalink to &quot;2. 选本地还是云端&quot;">​</a></h3><p>桌面应用的输入框有 <strong>Work locally</strong>。若出现 <strong>Cloud</strong>，按任务选：</p><table tabindex="0"><thead><tr><th></th><th><strong>Cloud</strong></th><th><strong>Work locally</strong></th></tr></thead><tbody><tr><td>跑在哪</td><td>OpenAI 托管的隔离环境</td><td>你的电脑</td></tr><tr><td>关应用 / 关机</td><td>能继续，可从网页或手机接着看</td><td>停</td></tr><tr><td>本地文件 / 本机应用</td><td>不能直接摸；靠上传、Project、已授权插件</td><td>可以</td></tr><tr><td>网页 Work</td><td>网页上的 Work <strong>就是</strong>云端</td><td>仅桌面</td></tr><tr><td>适合</td><td>长任务、定时盯网页、跨设备续跑</td><td>整理本机目录、操控本机应用</td></tr></tbody></table><p>云端定时任务不依赖电脑醒着。需要本机文件的定时任务，电脑要开机且桌面应用要开着。</p><h3 id="_3-写清结果-而不是写清心情" tabindex="-1">3. 写清结果，而不是写清心情 <a class="header-anchor" href="#_3-写清结果-而不是写清心情" aria-label="Permalink to &quot;3. 写清结果，而不是写清心情&quot;">​</a></h3><p>差的提示：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我做一份客户调研 PPT。</span></span></code></pre></div><p>官方推荐的形状：产出、来源、约束、何谓够好、何时停下来给你审。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>审阅附件里的访谈笔记和问卷结果。为产品管理层会做八页演示。</span></span>
<span class="line"><span>只讲三个最常见的客户问题，每条附证据，发现和建议分开，证据不足的主张标出来。</span></span>
<span class="line"><span>源文档用 @Google Drive。先交一版草稿给我审，不要当成定稿。</span></span></code></pre></div><h2 id="官方建议先试的三件事" tabindex="-1">官方建议先试的三件事 <a class="header-anchor" href="#官方建议先试的三件事" aria-label="Permalink to &quot;官方建议先试的三件事&quot;">​</a></h2><h3 id="做演示稿" tabindex="-1">做演示稿 <a class="header-anchor" href="#做演示稿" aria-label="Permalink to &quot;做演示稿&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>根据附件材料，为 [audience] 做八页演示。抓住主线，附证据，需要人审的地方标出来。先交草稿。</span></span></code></pre></div><h3 id="做对比表" tabindex="-1">做对比表 <a class="header-anchor" href="#做对比表" aria-label="Permalink to &quot;做对比表&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>为 [decision] 做一张对比表。用附件笔记和材料。列出最重要的标准、给每个选项打分、标风险和缺信息，并加一页摘要写推荐和下一步。</span></span></code></pre></div><h3 id="做定期更新" tabindex="-1">做定期更新 <a class="header-anchor" href="#做定期更新" aria-label="Permalink to &quot;做定期更新&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>每周一早上，查看 @Slack 和 @Google Drive 里 [project] 的新更新。</span></span>
<span class="line"><span>刷新会议议程：决策、阻塞、负责人、未决问题。分享前先把草稿发给我。</span></span></code></pre></div><p>定时任务的管理入口是侧栏 <strong>Scheduled</strong>。细节见 <a href="https://learn.chatgpt.com/docs/automations?surface=app" target="_blank" rel="noreferrer">Scheduled tasks</a>。</p><h2 id="插件-接到你真正在用的工具" tabindex="-1">插件：接到你真正在用的工具 <a class="header-anchor" href="#插件-接到你真正在用的工具" aria-label="Permalink to &quot;插件：接到你真正在用的工具&quot;">​</a></h2><p>插件是 Work 侧对位 Claude Connectors 的东西：Slack、Google Drive、SharePoint、日历、邮件、CRM、项目跟踪。</p><ol><li>左侧 <strong>Plugins</strong> 打开目录并安装。</li><li>提示词里用 <code>@插件名</code> 点名。</li><li>可用性取决于套餐、workspace 和插件本身。</li></ol><p>Enterprise / Edu 默认关插件；Business 默认开。管理员放开不等于你的账号已经授权——还要自己打开并登录。</p><p>编程仓库、CI、自建 MCP 仍走 <a href="./integration.html">项目集成</a>，不要和 Work 插件混成一件事。</p><h2 id="sites-需要托管页面时" tabindex="-1">Sites：需要托管页面时 <a class="header-anchor" href="#sites-需要托管页面时" aria-label="Permalink to &quot;Sites：需要托管页面时&quot;">​</a></h2><p><a href="https://learn.chatgpt.com/docs/sites" target="_blank" rel="noreferrer">Sites</a> 是公开测试：让 ChatGPT 创建、托管、改、分享网站、内部工具或小应用，不必另搭部署栈。网页入口 <a href="https://chatgpt.com/sites" target="_blank" rel="noreferrer">chatgpt.com/sites</a>。完整教程：<a href="./sites.html">Sites</a>。</p><p>它<strong>不是</strong> Claude Design 那种「从代码库抽品牌规范再交接实现」的设计产品。它是托管工作流。</p><p>约束（官方原文级）：</p><ul><li>每个部署 URL 都是生产环境。要先审，就让它 <strong>save a version without deploying</strong>。</li><li>CLI / IDE <strong>没有</strong> Sites 管理界面；创建和发布在网页或桌面应用。</li><li>企业 workspace 默认关公网发布。</li><li>不支持数据驻留；不要用它处理 PHI 或卡数据。</li></ul><p>前端工程师的用法：先在仓库里用 Codex 写和测，再让 Sites 发布；或用 Work 快速出内部看板，不要把它当成生产前端栈。</p><h2 id="桌面上-work-和-codex-怎么选" tabindex="-1">桌面上 Work 和 Codex 怎么选 <a class="header-anchor" href="#桌面上-work-和-codex-怎么选" aria-label="Permalink to &quot;桌面上 Work 和 Codex 怎么选&quot;">​</a></h2><p>官方对照（<a href="https://learn.chatgpt.com/docs/use-chatgpt#compare-chatgpt-work-and-codex-on-desktop" target="_blank" rel="noreferrer">Use ChatGPT</a>）：</p><table tabindex="0"><thead><tr><th>差异</th><th>ChatGPT（含 Work）</th><th>桌面里的 Codex</th></tr></thead><tbody><tr><td>从哪进</td><td>选 <strong>ChatGPT</strong>，再切 <strong>Work</strong></td><td>产品选择器里选 <strong>Codex</strong></td></tr><tr><td>看到的会话</td><td>网页/手机上的 Chat + Work</td><td>Codex 会话和开发项目</td></tr><tr><td>技术细节</td><td>默认藏起 Git / shell</td><td>显示 diff、评审视图</td></tr><tr><td>说话方式</td><td>偏非技术、成品导向</td><td>可以很技术</td></tr><tr><td>PR 面板</td><td>Work 里没有</td><td>开启后可用</td></tr></tbody></table><p>写代码、看 diff、处理 PR → Codex。要一份别人能打开的 PPT / 表 / 站点 → Work。</p><h2 id="安全边界-够日常用的那几条" tabindex="-1">安全边界（够日常用的那几条） <a class="header-anchor" href="#安全边界-够日常用的那几条" aria-label="Permalink to &quot;安全边界（够日常用的那几条）&quot;">​</a></h2><ul><li><strong>云端浏览器</strong>不是你电脑上的 Chrome：没有本地标签、扩展、历史、密码，也不能登录或付款。做不到的步骤它会停。</li><li><strong>本机 Work</strong> 能摸到你授权的本地文件和应用。不要把密钥目录交给它。</li><li>关键动作（花钱、改账号、对外发送）前先看批准提示。</li><li>管理员限制高于个人开关。「允许公网」不能盖过 workspace 策略。</li></ul><p>企业侧的隔离、保留和合规见 <a href="https://learn.chatgpt.com/docs/enterprise/chatgpt-work-overview" target="_blank" rel="noreferrer">ChatGPT Work Overview</a>。</p><h2 id="常见陷阱" tabindex="-1">常见陷阱 <a class="header-anchor" href="#常见陷阱" aria-label="Permalink to &quot;常见陷阱&quot;">​</a></h2><table tabindex="0"><thead><tr><th>陷阱</th><th>实际会发生什么</th><th>正确做法</th></tr></thead><tbody><tr><td>短问题也开 Work</td><td>多步代理更费额度</td><td>问答用 Chat</td></tr><tr><td>在 Work 里改仓库并指望 PR 面板</td><td>Work 没有 PR 侧栏</td><td>切到 Codex</td></tr><tr><td>关电脑还指望本地定时任务</td><td>任务不跑</td><td>不依赖本机的改 Cloud</td></tr><tr><td>把 Sites 当预览环境</td><td>部署 URL 就是生产</td><td>先 save version，批准后再 deploy</td></tr><tr><td>提示词里只写「做个 PPT」</td><td>空泛成品，证据对不上</td><td>写清受众、来源、停下来给你审</td></tr><tr><td>以为装了插件就等于已授权</td><td>企业默认关，还要个人登录</td><td>目录里启用并完成 OAuth</td></tr></tbody></table><h2 id="实际用例" tabindex="-1">实际用例 <a class="header-anchor" href="#实际用例" aria-label="Permalink to &quot;实际用例&quot;">​</a></h2><p>前端周会：Work 从 <code>@Slack</code> 和 <code>@Google Drive</code> 抽本周决策，出一页议程草稿；真正的代码改动丢给 <a href="./codex-cli.html">Codex CLI</a> 或桌面 Codex。设计对话留在 Chat，实现会话不要混进同一条 Work 线程。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ol><li>分不清该用哪个 → 回 <a href="./">学习地图</a> 的决策树。</li><li>要写代码 → <a href="./codex-cli.html">Codex CLI</a> 或 <a href="./codex-ai.html">产品线</a>。</li><li>要查套餐和 Chat 入口 → <a href="./chatgpt-plus.html">ChatGPT 套餐与访问</a>。</li><li>要把仓库接到 Agent → <a href="./integration.html">项目集成</a>。</li></ol><h2 id="官方来源" tabindex="-1">官方来源 <a class="header-anchor" href="#官方来源" aria-label="Permalink to &quot;官方来源&quot;">​</a></h2><ul><li><a href="https://learn.chatgpt.com/docs/get-started-with-work" target="_blank" rel="noreferrer">Get started with ChatGPT Work</a></li><li><a href="https://learn.chatgpt.com/docs/use-chatgpt" target="_blank" rel="noreferrer">Use ChatGPT</a>（Chat / Work / Codex 对照）</li><li><a href="https://learn.chatgpt.com/docs/app" target="_blank" rel="noreferrer">ChatGPT desktop app</a></li><li><a href="https://learn.chatgpt.com/docs/automations" target="_blank" rel="noreferrer">Scheduled tasks</a></li><li><a href="https://learn.chatgpt.com/docs/sites" target="_blank" rel="noreferrer">Sites</a></li><li><a href="https://learn.chatgpt.com/docs/plugins" target="_blank" rel="noreferrer">Plugins</a></li><li><a href="https://learn.chatgpt.com/docs/enterprise/chatgpt-work-overview" target="_blank" rel="noreferrer">ChatGPT Work Overview</a>（企业边界）</li><li><a href="https://learn.chatgpt.com/docs/whats-new" target="_blank" rel="noreferrer">What&#39;s new</a>（2026-07-09 Work 与桌面合并）</li></ul>`,62)])])}const f=a(d,[["render",s]]);export{u as __pageData,f as default};
